pub fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    s.iter()
        .map(|&c| {
            if ('A'..='Z').contains(&c) {
                ((c as u32) + 32)
                    .try_into()
                    .expect("ASCII uppercase + 32 must be valid char")
            } else {
                c
            }
        })
        .collect()
}

